/// <summary>
///     The <c>AVAPriceDiscAdmFrm_PriceDiscAdmTransDS_Extension</c> class is the extension for <c>InventSite</c>
///     AVA - Schneider 06.05.2024
/// </summary>
[ExtensionOf(formDataSourceStr(PriceDiscAdm, PriceDiscAdmTrans))]
final class AVAPriceDiscAdmFrm_PriceDiscAdmTransDS_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>active</c> method.
///     AVA - Schneider 06.05.2024
/// </summary>
/// <returns>
///     <c>int</c> as return value
/// </returns>
public int active()
{
    int                 retVal;

    PriceDiscAdmTable   locPriceDiscAdmTable;
    FormDataSource      locPriceDiscAdmTransDS;
    PriceDiscAdmTrans   locPriceDiscAdmTrans;
    FormCheckBoxControl locFormCheckBoxControl;

    retVal = next active();

    locPriceDiscAdmTransDS  = element.PriceDiscAdmTrans_DS;
    locPriceDiscAdmTrans    = locPriceDiscAdmTransDS.cursor();
    locFormCheckBoxControl  = element.PriceDiscAdmTrans_AVAEffectivePrice;

    if(locPriceDiscAdmTrans.RecId)
    {
        locPriceDiscAdmTable = PriceDiscAdmTable::find(locPriceDiscAdmTrans.JournalNum);
        if(     locPriceDiscAdmTable.RecId 
            &&  locPriceDiscAdmTable.Posted == NoYes::No)
        {
            if(locPriceDiscAdmTrans.relation == PriceType::PricePurch)
            {
                locFormCheckBoxControl.enabled(true);
                locFormCheckBoxControl.allowEdit(true);
            }
            else
            {
                locFormCheckBoxControl.enabled(false);
                locFormCheckBoxControl.allowEdit(false);
            }
        }
    }

    return retVal;
}
